        if is_be:
            base_exclude_block = blocks[1]
        else:
            plan_block = blocks[1]
    else:
        endpoint_block = blocks[0]
        # Find base/exclude and plan among remaining blocks
        for b in blocks[1:]:
            is_be = any(l.strip().split()[0].lower() in {'base', 'exclude'} for l in b if l.strip())
            if is_be and not base_exclude_block:
                base_exclude_block = b
            elif not plan_block:
                plan_block = b

    # Parse ENDPOINTS
    endpoints = []
    canonical_paths = {}
    seen_tuples = set()

    for line in endpoint_block:
        parts = line.strip().split()
        if len(parts) != 4:
