        path, method, role, permission = parts
        path = path.strip()
        role = role.strip()
        method_u = method.upper()
        perm_u = permission.upper()

        if not path or not role:
            break
        if method_u not in VALID_METHODS or perm_u not in VALID_PERMISSIONS:
            break
        if not re.match(r'^[a-zA-Z0-9_-]+$', role):
            break

        norm_path = VAR_PATTERN.sub('{var}', path)
        if norm_path not in canonical_paths:
            canonical_paths[norm_path] = path

        tup = (norm_path, method_u, role)
        if tup in seen_tuples:
            continue
        seen_tuples.add(tup)

        endpoints.append({
            'orig_path': path,
            'norm_path': norm_path,
            'method': method_u,
            'role': role,
            'permission': perm_u,
            'input_order': len(endpoints)
