        if kw == 'base' and len(parts) > 1:
            base_path = parts[1].strip()
        elif kw == 'exclude':
            excluded_roles.update(parts[1:])

    # Filter base endpoints
    norm_base = VAR_PATTERN.sub('{var}', base_path) if base_path else None
