        segs = [s for s in e['norm_path'].split('/') if s]
        num_segs = len(segs)
        return (-num_segs, e['method'], e['role'], e['permission'], path_for_output)

    selected.sort(key=sort_key)

    out_lines = []
    for e in selected:
        out_path = canonical_paths[e['norm_path']]
        out_lines.append(f"{out_path} {e['method']} {e['role']} {e['permission']}")

    return "\n".join(out_lines) + "\n"

